                info=doc.extract_image(xref)
                image={'xref':xref,'width':info.get('width'),'height':info.get('height'),'ext':info.get('ext'),'colorspace':info.get('colorspace'),'bpc':info.get('bpc'),'size':len(info.get('image',b''))}
            except Exception as e: image={'xref':xref,'error':str(e)}
            page_rec['images'].append(image)
        try:
            page_rec['annots']=[{'type':a.type,'info':a.info,'rect':list(a.rect),'uri':a.uri} for a in (page.annots() or [])]
        except Exception as e: page_rec['annots']=[{'error':str(e)}]
        try:
            page_rec['widgets']=[{'field_name':w.field_name,'field_value':w.field_value,'field_type':w.field_type,'rect':list(w.rect)} for w in (page.widgets() or [])]
        except Exception as e: page_rec['widgets']=[{'error':str(e)}]
        rec['pages'].append(page_rec)
    try:
        reader=PdfReader(path, strict=False)
        rec['pypdf_metadata']={str(k):str(v) for k,v in (reader.metadata or {}).items()}
        rec['pypdf_root_keys']=sorted(str(k) for k in reader.trailer.get('/Root',{}).keys())
        rec['pypdf_names_keys']=sorted(str(k) for k in reader.trailer.get('/Root',{}).get('/Names',{}).keys()) if reader.trailer.get('/Root',{}).get('/Names') else []
        rec['pypdf_page_annots']=[len(page.get('/Annots',[])) if page.get('/Annots') else 0 for page in reader.pages]
        rec['pypdf_acroform']=str(reader.trailer.get('/Root',{}).get('/AcroForm'))
        rec['pypdf_open_action']=str(reader.trailer.get('/Root',{}).get('/OpenAction'))
    except Exception as e: rec['pypdf_error']=str(e)
    with open(f'{outdir}/paper{idx}.json','w') as f: json.dump(rec,f,indent=2,default=str)
    with open(f'{outdir}/paper{idx}.txt','w') as f:
        for p in rec['pages']:
            f.write(f'\n===== PAGE {p["page"]} =====\n{p["text"]}')
    subprocess.run(['pdftotext','-layout',path,f'{outdir}/paper{idx}.pdftotext'],check=False)
    print(f'paper{idx}: pages={len(doc)}, metadata_keys={list((doc.metadata or {}).keys())}, outline={len(rec["outline"])}, attachments={rec["embfile_names"]}, images={sum(len(p["images"]) for p in rec["pages"])}')
