# Rectangles cover only identity-bearing lines, with a small glyph-safe margin.
def safe_rect(values, margin=0.8):
    r = fitz.Rect(*values)
    return fitz.Rect(r.x0-margin, r.y0-margin, r.x1+margin, r.y1+margin)

def add_rect(doc, page_no, values, label, log):
    page = doc[page_no]
    rect = safe_rect(values)
    page.add_redact_annot(rect, fill=(1, 1, 1), cross_out=False)
    log.append({'page': page_no+1, 'label': label, 'rect': list(rect)})

def add_search(doc, page_no, phrase, label, log):
    page = doc[page_no]
    rects = page.search_for(phrase)
    if not rects:
        raise RuntimeError(f'Could not locate required target {phrase!r} on page {page_no+1}')
    for rect in rects:
        rect = safe_rect(rect, 0.6)
        page.add_redact_annot(rect, fill=(1, 1, 1), cross_out=False)
        log.append({'page': page_no+1, 'label': label, 'phrase': phrase, 'rect': list(rect)})

plans = {
    1: {
        'refs_page': 9,
        'rects': [
            (0, (112.5, 134.2, 467.5, 160.6), 'author names and markers'),
            (0, (112.5, 158.0, 397.0, 189.5), 'affiliations and correspondence'),
            (0, (9.5, 213.5, 39.0, 578.5), 'arXiv identifier side banner'),
            (1, (119.5, 719.8, 404.5, 733.2), 'author-specific code/data disclosure'),
        ],
        'searches': [],
    },
    2: {
        'refs_page': 4,
        'rects': [
            (0, (62.8, 134.4, 534.2, 163.7), 'author names and markers'),
            (0, (63.5, 167.6, 533.5, 213.4), 'affiliations and correspondence'),
            (0, (56.6, 694.8, 285.5, 720.2), 'equal/corresponding-author footnotes'),
            (0, (55.8, 26.5, 201.4, 52.7), 'accepted venue header'),
            (0, (284.8, 796.8, 538.8, 812.2), 'venue DOI footer'),
            (3, (311.8, 658.2, 540.4, 744.2), 'funding and acknowledgements'),
        ],
        'searches': [
            (0, 'https://github.com/espnet/espnet', 'dataset/code URL'),
            (0, 'https://huggingface.co/datasets/espnet/', 'dataset URL'),
            (0, '10.21437/Interspeech.2024-33', 'venue DOI'),
        ],
    },
    3: {
        'refs_page': 4,
        'rects': [
            (0, (80.2, 136.7, 515.5, 167.0), 'author names and markers'),
            (0, (54.3, 655.1, 545.0, 718.4), 'affiliation, correspondence, funding, venue, copyright'),
            (3, (54.7, 695.0, 291.3, 718.0), 'author-identifying library URL'),
        ],
        'searches': [],
    },
}

redaction_log = {}
for idx, src in sources.items():
    doc = fitz.open(src)
    log=[]
    for page_no, rect, label in plans[idx]['rects']:
        add_rect(doc, page_no, rect, label, log)
    for page_no, phrase, label in plans[idx]['searches']:
        add_search(doc, page_no, phrase, label, log)

    # Remove external links before References; retain ordinary internal citation navigation.
    deleted_links=[]
    for page_no in range(plans[idx]['refs_page']):
        page=doc[page_no]
        for link in list(page.get_links()):
            if link.get('kind') == fitz.LINK_URI:
                deleted_links.append({'page':page_no+1,'uri':link.get('uri','')})
                page.delete_link(link)
    # Remove any comments or form widgets, if present; inventory found none in these sources.
    deleted_annots=0
    for page in doc:
        for annot in list(page.annots() or []):
            page.delete_annot(annot)
            deleted_annots += 1
        for widget in list(page.widgets() or []):
            page.delete_widget(widget)
            deleted_annots += 1

    for page in doc:
        if page.first_annot:
            raise RuntimeError(f'Unexpected annotation remained before redaction on paper {idx}')
        if page.widgets():
            raise RuntimeError(f'Unexpected widget remained before redaction on paper {idx}')
        if page.get_links():
            # Only internal links are retained, and they do not carry author URLs.
            for link in page.get_links():
