 outline_ids=set()
 def collect_outline(ref):
  if not isinstance(ref,IndirectObject): return
  key=(ref.idnum,ref.generation)
  if key in outline_ids: return
  outline_ids.add(key)
  try: d=ref.get_object()
  except Exception: return
  if isinstance(d,DictionaryObject):
   for k in ('/First','/Next','/Last'):
    if k in d: collect_outline(d[k])
 try:
  root=reader.trailer['/Root'].get_object()
  if '/Outlines' in root: collect_outline(root['/Outlines'])
 except Exception: pass
 removed=[]
 for gen,table in reader.xref.items():
  for objnum in table:
   try: obj=IndirectObject(objnum,gen,reader).get_object()
   except Exception: continue
   if not isinstance(obj,DictionaryObject): continue
   protected=(objnum,gen) in outline_ids
   for key in list(obj.keys()):
    keystr=str(key)
    if keystr == '/Title' and protected: continue
    if keystr in metadata_keys or (keystr == '/Title' and not protected):
     removed.append((objnum,gen,keystr)); del obj[key]
 # Remove any trailer Info and document metadata references explicitly.
 if '/Info' in reader.trailer: del reader.trailer['/Info']
 try:
  root=reader.trailer['/Root'].get_object()
  if '/Metadata' in root: del root['/Metadata']
 except Exception: pass
 writer=PdfWriter()
 writer.clone_document_from_reader(reader)
 writer.add_metadata({'/Producer':'pypdf','/Creator':'pypdf'})
 tmp=path+'.tmp'
 with open(tmp,'wb') as f: writer.write(f)
 os.replace(tmp,path)
 print(os.path.basename(path),'removed_object_metadata_fields=',len(removed),'outline_nodes_protected=',len(outline_ids))
